/**
 * Small helpers for random tokens and hashing.
 */
import crypto from 'node:crypto';

/** 32 random bytes, safe to put in a cookie or a header. */
export function newToken(): string {
  return crypto.randomBytes(32).toString('base64url');
}

/** A random id generated by the server, for example for users and audit events. */
export function newId(): string {
  return crypto.randomUUID();
}

export function sha256(value: string): string {
  return crypto.createHash('sha256').update(value).digest('hex');
}

/** Compares two strings in constant time, so the time taken does not leak where they differ. */
export function safeEqual(a: string, b: string): boolean {
  const bufferA = Buffer.from(a);
  const bufferB = Buffer.from(b);
  if (bufferA.length !== bufferB.length) {
    return false;
  }
  return crypto.timingSafeEqual(bufferA, bufferB);
}
